style.css:
@-moz-document domain("outlook.office.com"), domain("word.office.com"), domain("excel.office.com"), domain("onedrive.live.com") {
body {
        background-color: #ffd6e5 !important; /* Soft pink background */
        color: #5a1a3e !important; /* Dark pink text */
    }

    /* Sidebar & top bar */
    .ms-Fabric, .ms-Nav, .ms-CommandBar {
        background-color: #ffb6c1 !important; /* Light pink */
    }

    /* Buttons & links */
    a, button {
        color: #ff4081 !important; /* Bright pink */
    }

    /* Hover effects */
    a:hover, button:hover {
        background-color: #ff80ab !important; /* Softer pink */
    }
}
